/* Operation and audit presentation; all actions use existing guarded handlers. */
(() => { 'use strict';window.GpoOperationView=Object.freeze({create({state,esc,say,tr,successful,statusText,stateClass}){
function operationsView(){
  const all=state.history,q=state.opsQuery.trim().toLowerCase();
  const matchesQuery=h=>!q||`${h.plan?.selection?.setting||''} ${h.plan?.preview?.gpo?.name||''} ${h.approval?.changeReference||''} ${h.plan?.executionUser||''} ${h.result?.state||''}`.toLowerCase().includes(q);
  const matchesFilter=h=>{const value=String(h.result?.state||'').toUpperCase(),evidence=value+' '+String(h.result?.effectiveStatus||'').toUpperCase();return state.opsFilter==='ALL'||(state.opsFilter==='SUCCESS'&&GpoUiDomain.classify(h).compliant)||(state.opsFilter==='FAILED'&&/FAIL|REVIEW|PARTIAL/.test(evidence))||(state.opsFilter==='DRIFT'&&/DRIFT|MISMATCH/.test(evidence))||value===state.opsFilter;};
  const drift=all.filter(h=>/DRIFT|MISMATCH/.test(String(h.result?.state||'')+' '+String(h.result?.effectiveStatus||'').toUpperCase())),filtered=window.GpoProduct.sortedRuns(all.filter(h=>matchesFilter(h)&&matchesQuery(h)),state.opsSort);
  const paged=window.GpoListPager.page(filtered,state.opsPage,50),visible=paged.items;
  const metrics=[['ALL','All',all.length],['SUCCESS','Verified',all.filter(successful).length],['DRIFT','Drift',drift.length],['FAILED','Needs review',all.filter(h=>/FAIL|REVIEW|PARTIAL/.test(String(h.result?.state||'')+' '+String(h.result?.effectiveStatus||'').toUpperCase())).length],['ROLLED_BACK','Rolled back',all.filter(h=>String(h.result?.state||'').toUpperCase()==='ROLLED_BACK').length]];
  return `<header class="page-header"><div><span class="page-kicker">${'CHANGE JOURNAL'}</span><h1>${tr('operations')}</h1><p>${'Track outcome, verification, and recovery details for every change.'}</p></div><a class="page-primary" href="#/benchmark">${'Create new plan'} <span>→</span></a></header>
  <section class="ops-summary" aria-label="${'Operation summary'}">${metrics.map(([key,label,count])=>`<button data-ops-filter="${key}" class="summary-card ${state.opsFilter===key?'active':''}"><span>${label}</span><strong>${count}</strong></button>`).join('')}</section>
  ${drift.length?`<section class="attention-panel"><div><span>${'ATTENTION'}</span><h2>${drift.length} ${'operation(s) have drift'}</h2><p>${'Live state differs from the expected result.'}</p></div><button data-ops-filter="DRIFT">${'Show drift'}</button></section>`:''}
  <section class="ops-search-panel"><div class="searchbox"><span>⌕</span><input id="ops-search" value="${esc(state.opsQuery)}" placeholder="${'Search control, GPO, change ID, or operator'}"></div><div class="product-sort"><span>${filtered.length} ${'result(s)'}</span><select id="ops-sort" aria-label="${'Operation order'}">${[['newest','Newest first'],['oldest','Oldest first'],['attention','Needs attention first']].map(([v,l])=>`<option value="${v}" ${state.opsSort===v?'selected':''}>${l}</option>`).join('')}</select></div></section>
  ${window.GpoListPager.render('ops',paged)}${window.GpoComponents.activity(state,visible)}${filtered.length?`<div class="ds-ops-switch" role="group" aria-label="${'Operations view'}"><button data-ops-layout="table" aria-pressed="${state.opsLayout==='table'}">${'Table'}</button><button data-ops-layout="cards" aria-pressed="${state.opsLayout==='cards'}">${'Cards'}</button></div>${state.opsLayout==='table'?window.GpoComponents.operations(state,visible):`<div class="ops-list">${visible.map(operationCard).join('')}</div>`}`:`<section class="empty-state"><div class="empty-state-icon">${window.GpoPremium.emptyIcon()}</div><h2>${q?'No matching result':'No operations yet'}</h2><p>${q?'Adjust the search term or filter.':'Create the first read-only plan from Benchmark. Every change will appear here.'}</p>${q?`<button data-ops-filter="ALL">${'Show all'}</button>`:`<a href="#/benchmark">${'Open benchmark'} →</a>`}</section>`}`;
}
function auditView(){
  if(!state.audit)return `<section class="content-card audit-loading"><h1>${'Audit journal'}</h1><p>${'Loading hash-chain audit events…'}</p><button data-load-audit>${'Load audit'}</button></section>`;
  const q=state.auditQuery.trim().toLowerCase(),events=(state.audit.events||[]).filter(e=>!q||`${e.event} ${e.operator} ${e.jobId||''} ${e.controlId||''} ${e.gpoId||''} ${e.createdAt}`.toLowerCase().includes(q));
  const paged=window.GpoListPager.page(events,state.auditPage,100);
  return `<div class="hero compact"><div><span class="eyebrow">${'APPEND-ONLY EVENT JOURNAL'}</span><h1>${'Audit'}</h1><p>${'Inspect event, actor, time, GPO, correlation context, and chain integrity.'}</p></div><div class="integrity-card ${state.audit.integrityValid?'ok':'bad'}"><span>${'CHAIN INTEGRITY'}</span><strong>${state.audit.integrityValid?'Valid':'BROKEN'}</strong></div></div>${window.GpoComponents.auditChain(state)}<div class="audit-toolbar"><div class="searchbox"><span>⌕</span><input id="audit-search" value="${esc(state.auditQuery)}" placeholder="${'Search event, actor, GPO, or correlation…'}"></div><button data-export-audit>${'Export JSON'}</button><button data-load-audit>${'Refresh'}</button></div><div class="audit-event-table" role="table"><div class="audit-event-head" role="row"><span>${'Time'}</span><span>${'Event'}</span><span>${'Actor'}</span><span>GPO / Control</span><span>Hash</span></div>${paged.items.map(e=>`<div class="audit-event-row" role="row"><span><time datetime="${esc(e.createdAt)}">${new Date(e.createdAt).toLocaleString('en-GB')}</time><small>#${e.id}</small></span><span><b>${esc(e.event)}</b><small>${esc(e.jobId||'—')}</small></span><span>${esc(e.operator)}</span><span>${esc(e.gpoId||'—')}<small>${esc(e.controlId||'—')}</small></span><span class="hash-cell" title="${esc(e.hash)}">${window.GpoPremium.copyValue(state,e.hash,'Hash')}</span></div>`).join('')||`<div class="panel-empty">${'No matching audit event.'}</div>`}</div>${window.GpoListPager.render('audit',paged)}`;
}
function operationCard(h){const rr=h.result?.refreshResults||[],drift=/DRIFT|MISMATCH|REVIEW|FAIL/.test(String(h.result?.state||'')+' '+String(h.result?.effectiveStatus||'')),m=h.plan?.selection?.setting||'Control';const stages=[['Preview',true],['Approved',!!h.approval],['Backup',!!h.result?.backupId],['Applied',!!h.result?.gpoPublished],['Verified',!!h.result?.linkVerified],['gpupdate',rr.length>0&&rr.every(x=>['OK','SUCCESS'].includes(x.state))],['Effective',stateClass(h.result?.effectiveStatus)==='ok']];return `<article class="op-card ${drift?'needs-attention':''}"><div class="op-main">${window.GpoComponents.status(state,window.GpoUiDomain.resultState(h)).html}<div><h2>${esc(m)} · ${esc(h.plan?.preview?.gpo?.name||'GPO operation')}</h2><p>${esc(h.result?.message||'')}</p><div class="op-meta"><span>${esc(h.plan?.preview?.scope?.dn||'—')}</span><span>${esc(h.plan?.executionUser||'—')}</span><span>${new Date(h.updatedAt||0).toLocaleString()}</span>${h.approval?.changeReference?`<span>Change ${esc(h.approval.changeReference)}</span>`:''}${h.correlationId?`<span title="Correlation ID">CID ${esc(h.correlationId.slice(0,12))}</span>`:''}</div></div></div><div class="op-timeline">${stages.map(([label,done])=>`<div class="${done?'done':''}"><b>${done?'✓':'·'}</b><span>${label}</span></div>`).join('')}</div><div class="op-live-diff"><div><small>BEFORE</small><strong>${esc(h.plan?.preview?.previousValue??'Not configured')}</strong>${window.GpoComponents.valueSource(h.plan?.preview?.previousValueSource,h.plan?.preview?.previousValue,h.plan?.preview?.gpo)}</div><div><small>EXPECTED</small><strong>${esc(h.plan?.preview?.desiredValue??'—')}</strong></div><div><small>${h.result?.domainPolicy?'ACTUAL AD VALUE':'STORED GPO VALUE'}</small><strong>${esc(h.result?.domainPolicy?.value??h.result?.currentValue??'—')}</strong>${h.result?.domainPolicy?`<small>AD ${esc(h.result.domainPolicy.property)}</small>`:window.GpoComponents.valueSource(h.result?.currentValueSource,h.result?.currentValue,h.plan?.preview?.gpo)}</div></div><div class="op-actions"><button class="product-detail-button" data-inspect="${esc(h.id)}">${'View details'} ↗</button><button data-verify="${esc(h.id)}" title="Read current live state">Re-verify</button>${h.result?.state!=='ROLLED_BACK'&&h.plan?.selection?.refresh&&h.result?.gpoPublished&&h.result?.linkVerified?`<button data-gpupdate="${esc(h.id)}" title="Explicitly schedule gpupdate /force">gpupdate /force</button>`:''}${drift&&(!h.result?.gpoPublished||!h.result?.linkVerified)?`<button class="primary-action" data-replan="${esc(h.id)}">Remediate again</button>`:''}<button data-op-evidence="${esc(h.id)}">Evidence</button></div>${window.GpoComponents.recovery(state,h)}</article>`;}

const renderOperationCard=operationCard;
operationCard=function(h){
 if(h?.plan?.selection?.refresh==='None')h={...h,plan:{...h.plan,selection:{...h.plan.selection,refresh:''}}};
 return renderOperationCard(h);
};
return {operationsView,auditView};}});})();
